from typing import Optional

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class StatusSetResponseSchema(BaseRapiResponseSchema): ...


class Status(pydantic.BaseModel):
    media: str
    text: str
    duration: Optional[int] = None


class StatusListResultsSchema(pydantic.BaseModel):
    hash: str
    statuses: list[Status]


class StatusListResponseSchema(BaseRapiResponseSchema):
    results: Optional[StatusListResultsSchema]
